// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@datatype class ProcessorTimingProperties(val clockPeriod: Option[Z],
                                          val framePeriod: Option[Z],
                                          val maxDomain: Option[Z],
                                          val slotTime: Option[Z])

@datatype class ThreadTimingProperties(val domain: Option[Z],
                                       val computeExecutionTime: Option[(Z, Z)])

object Schedulers {

  val threadNickNames: Map[String, Art.BridgeId] = Map(
    ISZ(
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_battery_observation_admission.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_battery_observation_admission.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_battery_capacity_assessment.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_battery_capacity_assessment.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_management_assessment.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_management_assessment.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_odd_engine_group_assessor.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_odd_engine_group_assessor.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_even_engine_group_assessor.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_even_engine_group_assessor.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_four_engine_configuration_assessor.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_four_engine_configuration_assessor.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_propulsion_evidence_composer.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_propulsion_evidence_composer.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_charging_interlock_assessor.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_charging_interlock_assessor.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_enable_demand_lifecycle.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_enable_demand_lifecycle.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_fault_action_priority_resolver.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_fault_action_priority_resolver.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_recovery_qualification.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_recovery_qualification.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_availability_decision_owner.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_availability_decision_owner.id,
      Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock.name ~> Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock.id)
  )

  val revThreadNickNames: Map[Art.BridgeId, String] = Map.empty[Art.BridgeId, String] ++ (for (e <- threadNickNames.entries) yield e._2 ~> e._1)


  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_battery_observation_admission_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_battery_capacity_assessment_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_management_assessment_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_odd_engine_group_assessor_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_even_engine_group_assessor_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_four_engine_configuration_assessor_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_propulsion_evidence_composer_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_charging_interlock_assessor_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_enable_demand_lifecycle_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_fault_action_priority_resolver_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_recovery_qualification_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_availability_decision_owner_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())


  /**********************************************************************
   * Round Robin Scheduler
   *********************************************************************/

  // roundRobinSchedule represents the component dispatch order
  val roundRobinSchedule: ISZ[Art.BridgeId] = {
    // convert IS[Art.BridgeId, art.Bridge] to an IS[Z, Art.BridgeId] to allow bridges to be dispatched
    // multiple times during a hyper-period
    var ret: ISZ[Art.BridgeId] = ISZ()
    for (e <- Arch.ad.components) {
      ret = ret :+ e.id
    }
    ret
  }

  def getRoundRobinScheduler(schedule: Option[ISZ[Art.BridgeId]]): RoundRobin = {
    if (roundRobinSchedule.isEmpty) {} // line needed for transpiler; do not remove
    schedule match {
      case Some(s) => return RoundRobin(s)
      case _ => return RoundRobin(ScheduleProviderI.getRoundRobinOrder())
    }
  }

  /**********************************************************************
   * Static Scheduler
   *********************************************************************/

  val framePeriod: Z = 1000
  val numComponents: Z = Arch.ad.components.size
  val maxExecutionTime: Z = numComponents / framePeriod

  // defaultStaticSchedule represents the component dispatch order
  val defaultStaticSchedule: DScheduleSpec = DScheduleSpec(0, 0, DSchedule(ISZ(
    Schedule.Slot(0, maxExecutionTime),
    Schedule.Slot(1, maxExecutionTime),
    Schedule.Slot(2, maxExecutionTime),
    Schedule.Slot(3, maxExecutionTime),
    Schedule.Slot(4, maxExecutionTime),
    Schedule.Slot(5, maxExecutionTime),
    Schedule.Slot(6, maxExecutionTime),
    Schedule.Slot(7, maxExecutionTime),
    Schedule.Slot(8, maxExecutionTime),
    Schedule.Slot(9, maxExecutionTime),
    Schedule.Slot(10, maxExecutionTime),
    Schedule.Slot(11, maxExecutionTime),
    Schedule.Slot(12, maxExecutionTime)
  )))

  val defaultDomainToBridgeIdMap: ISZ[Art.BridgeId] = ISZ(
    /* domain 0 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_battery_observation_admission.id,
    /* domain 1 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_battery_capacity_assessment.id,
    /* domain 2 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_management_assessment.id,
    /* domain 3 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_odd_engine_group_assessor.id,
    /* domain 4 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_even_engine_group_assessor.id,
    /* domain 5 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_four_engine_configuration_assessor.id,
    /* domain 6 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_propulsion_evidence_composer.id,
    /* domain 7 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_charging_interlock_assessor.id,
    /* domain 8 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_enable_demand_lifecycle.id,
    /* domain 9 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_fault_action_priority_resolver.id,
    /* domain 10 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_recovery_qualification.id,
    /* domain 11 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_availability_decision_owner.id,
    /* domain 12 */ Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock.id
  )

  def getStaticSchedulerH(userProvided: MOption[(DScheduleSpec, ISZ[Art.BridgeId], Map[String, Art.BridgeId], CommandProvider)]): StaticScheduler = {
    if (defaultStaticSchedule.schedule.slots.isEmpty && defaultDomainToBridgeIdMap.isEmpty && threadNickNames.isEmpty) {} // line needed for transpiler; do not remove
    userProvided match {
      case MSome((schedule_, domainToBridgeIdMap_, threadNickNames_, commandProvider)) =>
        return getStaticScheduler(schedule_, domainToBridgeIdMap_, threadNickNames_, commandProvider)
      case _ =>
        return getStaticScheduler(
          ScheduleProviderI.getStaticSchedule(),
          // TODO: get the following from extension so they can be customized via C
          defaultDomainToBridgeIdMap,
          threadNickNames,
          DefaultCommandProvider())
    }
  }

  def getStaticScheduler(schedule: DScheduleSpec,
                         domainToBridgeIdMap: ISZ[Art.BridgeId],
                         threadNickNames: Map[String, Art.BridgeId],
                         commandProvider: CommandProvider): StaticScheduler = {
    return StaticScheduler(schedule, Arch.ad.components, domainToBridgeIdMap, threadNickNames,
      if (commandProvider.isInstanceOf[InfoCommandProvider])
        commandProvider.asInstanceOf[InfoCommandProvider].init(
          threadNickNames,
          schedule.schedule.slots.size,
          domainToBridgeIdMap
        )
      else commandProvider)
  }


  /**********************************************************************
   * Legacy Scheduler
   *********************************************************************/

  def getLegacyScheduler(): Legacy = {
    return Legacy(Arch.ad.components)
  }
}

// the purpose of this extension is to allow users to provide custom schedules
// at the C level after transpiling
@ext(name = "ScheduleProvider") object ScheduleProviderI {
  def getRoundRobinOrder(): ISZ[Art.BridgeId] = $

  def getStaticSchedule(): DScheduleSpec = $
}